if (!entity) {
    this.onEntityDeselect();
    return;
}

const idKey = this.currentEntityIdKey;
if (this.currentEntity && entity[idKey] !== this.currentEntity[idKey]) {
    this.activity.notes.hasLoadedEntityNotes = false;
    this.activity.notes.currentNotes.length = 0;
    this.activity.calls.hasLoadedEntityCalls = false;
    this.activity.calls.currentCalls.length = 0;

    this.activity.eventLogs.hasLoadedEntityEventLogs = false;
    this.activity.eventLogs.currentEventLogs.length = 0;
}

if (this.isAddingEntity) {
    this.isSidePanelVisible = false;
    this.isAddingEntity = false;
}

this.currentEntity = entity;
this.currentEntityId = this.currentEntity[idKey];



if (this.isEditingEntity) {
    this.utilityService.populateForm(this.currentForm, this.currentEntity);
}

if (this.currentApiType === "crm" && this.currentEntityTypeHasActivities) {
    loadEntityActivities(this);
    loadEntityAttachments(this);
}

this.isSidePanelVisible = true;

this.currentEntityDetails = this.utilityService.formatEntityForDisplay(this.currentEntity);

/**
 * Loads Notes and Calls, and once complete, loads the Event Logs
 * for the entity and its related activities.
 */
function loadEntityActivities(ctx) {
    const promises = [];

    if (!ctx.activity.notes.hasLoadedEntityNotes && !ctx.activity.notes.isLoadingNotes) {
        ctx.activity.notes.isLoadingNotes = true;
        const notesPromise = ctx.activity.notes.loadEntityNotes()
            .then(() => ctx.activity.notes.hasLoadedEntityNotes = true)
            .finally(() => ctx.activity.notes.isLoadingNotes = false);
        promises.push(notesPromise);
    }

    if (!ctx.activity.calls.hasLoadedEntityCalls && !ctx.activity.calls.isLoadingCalls) {
        ctx.activity.calls.isLoadingCalls = true;
        const callsPromise = ctx.activity.calls.loadEntityCalls()
            .then(() => ctx.activity.calls.hasLoadedEntityCalls = true)
            .finally(() => ctx.activity.calls.isLoadingCalls = false);
        promises.push(callsPromise);
    }

    if (!ctx.activity.eventLogs.hasLoadedEntityEventLogs && !ctx.activity.eventLogs.isLoadingEventLogs) {
        ctx.activity.eventLogs.isLoadingEventLogs = true;
    }

    Promise.allSettled(promises).then(async () => {
        const loadLogsForEntityType = (entityType, currentItems, idPropertyName) => {
            if (currentItems?.length) {
                const mostRecentEntityId = ctx.utilityService.getMostRecentEntityId(currentItems, idPropertyName);
                return ctx.activity.eventLogs.loadEntityEventLogs(entityType, mostRecentEntityId);
            }
            return Promise.resolve();
        };

        const logPromises = [];

        logPromises.push(loadLogsForEntityType("activity_notes", ctx.activity.notes.currentNotes, "activityId"));
        logPromises.push(loadLogsForEntityType("activity_call", ctx.activity.calls.currentCalls, "activityId"));
        logPromises.push(ctx.activity.eventLogs.loadEntityEventLogs(ctx.currentEntityType, ctx.currentEntityId));

        await Promise.allSettled(logPromises);

        ctx.activity.eventLogs.hasLoadedEntityEventLogs = true;
        ctx.activity.eventLogs.isLoadingEventLogs = false;

        if (ctx.activity.eventLogs.currentEventLogs.length > 0) {
            ctx.utilityService.sortEntitiesByDateProperty(ctx.activity.eventLogs.currentEventLogs, "modifiedOn");
        }
    });
}

// Handle Attachments
function loadEntityAttachments(ctx) {
    ctx.attachmentService.uiState.currentPage = 1;
    ctx.attachmentService.uiState.targetEntityType = ctx.currentEntityType;
    ctx.attachmentService.uiState.targetEntityId = ctx.currentEntityId;
    ctx.attachmentService.uiState.targetEntityName = ctx.currentEntity.fullName ?? ctx.currentEntity.name ?? "";
    ctx.attachmentService.helpers._resetUploadState();
    ctx.attachmentService.loaders.loadAllAttachmentsByEntity();
}

if (this.isPipelineViewActive && !this.isMobile) {
    this.pipelineViewService.selectedDeal = null;
    this.pipelineViewService.selectedDealDetails = [];
} else {
    this.isSidePanelVisible = false;
    this.currentEntity = null;
    this.currentEntityId = null;
    this.currentSelectedRows = [];
}

this.isAssigningEntity = false;
this.isAddingEntity = false;
this.isEditingEntity = false;

// Reset Notes
this.activity.notes.hasLoadedEntityNotes = false;
this.activity.notes.currentNotes.length = 0;

// Reset Calls
this.activity.calls.hasLoadedEntityCalls = false;
this.activity.calls.currentCalls.length = 0;

// Reset Call Notes
this.activity.calls.notes.hasLoadedEntityNotes = false;
this.activity.calls.notes.currentNotes.length = 0;

// Reset Event Logs
this.activity.eventLogs.hasLoadedEntityEventLogs = false;
this.activity.eventLogs.currentEventLogs.length = 0;

const tabItemIndex = selectedTab - 1;
this.currentTabName = this.currentTabItems[tabItemIndex].label;

if (this.currentApiType === "auth") {
    this.currentEntityType = this.currentTabName.toLowerCase().slice(0, -1);
}

if (this.isAddingEntity) {
    this.isAddingEntity = false;
}

if (this.isEditingEntity) {
    this.isEditingEntity = false;
}

if (this.currentEntity) {
    this.currentEntity = undefined;
}

this.onPageChange(undefined, queryString, false);
return;

const { column: newColumn, operation: newOperation, target: newTarget } = changes;

if (newColumn === null && newOperation === null && newTarget === null) {
    this.onPageChange(this.currentPage, null, true)
    return;
}

// --- 1. Handle a change in the filter COLUMN ---
//    This is the primary trigger for resetting other fields.
if (newColumn !== undefined) {
    // When the column changes, always reset the rest of the filter.
    this.currentFilter.column = newColumn;
    this.currentFilter.operation = null;
    this.currentFilter.target = null;
    this.currentFilter.targetValues = []; // Clear any dropdown options
    this.isFilteringByPipelineOrPipelineStage = false;

    // Now, apply special logic if the new column is a pipeline/stage.
    if (["pipelineId", "pipelineStageId"].includes(newColumn)) {
        this.isFilteringByPipelineOrPipelineStage = true;
        this.currentFilter.operation = "eq"; // Force the operation to 'eq'.

        // Populate the dropdown for the target value based on the selected column.
        const sourceArray = newColumn === "pipelineId" ? this.currentPipelines : this.currentPipelineStages;
        const valueKey = newColumn === "pipelineId" ? "pipelineId" : "pipelineStageId";

        this.currentFilter.targetValues = this.utilityService.generateLabelValueArray({
            entityArray: sourceArray,
            labelKey: "name",
            valueKey: valueKey
        });
    }
}

// --- 2. Handle changes to OPERATION and TARGET values ---
if (newOperation !== undefined) {
    this.currentFilter.operation = newOperation;
}
if (newTarget !== undefined) {
    this.currentFilter.target = newTarget;
}

// --- 3. Build the query and trigger a data reload ---
const { column, operation, target } = this.currentFilter;

// If the target is explicitly set to empty string, it means the user cleared the filter.
if (target === "") {
    this.currentFilter.query = '';
    this.onPageChange(undefined, undefined, true);
    return;
}

// Only reload the data if all parts of the filter are complete.
if (column && operation && target) {
    this.currentFilter.query = _buildFilterQuery(this.currentFilter);
    this.onPageChange(undefined, this.currentFilter.query, false);
}

/**
 * Helper function to build the query string.
 * @private
 */
function _buildFilterQuery(currentFilter) {
    // This helper remains the same, it's a good separation of concerns.
    const { column, target, operation } = currentFilter;
    if (!column || !target || !operation) {
        return '';
    }
    return `${column}_${operation}=${target}`;
}

this.currentDataLoadId++;
const loadId = this.currentDataLoadId;
const limit = this.limit ?? 25;

const {
    createdNewEntity,
    entityId,
    changedTenant
} = options || {};

const currentEntityType = this.currentEntityType;
const isOpportunity = currentEntityType === "opportunity";
const titleCasedEntityType = isOpportunity ? "Deal" : currentEntityType[0].toUpperCase() + currentEntityType.slice(1);
this.currentDefaultConfig = {
    ...this.currentDefaultSearchConfig,
    columns: this.currentDefaultColumnConfig.columnNames
};

if (changedTenant) {
    this.is360ViewActive = false;
    if (this.isPipelineViewActive) {
        this.isPipelineViewActive = false;
        this.pipelineViewService.resetKanbanView();
    }
}

// Use the provided parameter, defaulting to page 1 if it's null/undefined.
if (currentPageParam) {
    this.currentPage = currentPageParam
} else {
    this.currentPage = 1;
}

if (this.currentApiType === "auth") {
    this.currentEntityIdKey = "id";
} else {
    this.currentEntityIdKey = currentEntityType + "Id";
}

this.entityService.entityType = currentEntityType;
this.entityService.displayColumnConfig = this.currentDisplayColumnConfig;

// --- 1. Update Filter State ---
if (externalQueryParam === null) {
    const { column, operation, target } = this.currentFilter;
    this.currentFilter = {
        column: null,
        operation: null,
        target: null,
        query: '',
        columnValues: this.currentFilter.columnValues,
        filtersApplied: [
            {
                property: null,
                operation: null,
                value: ""
            }
        ],
        sortsApplied: [
            {
                property: null,
                order: "ASC"
            }
        ]
    };

    // if (!column || !operation || !target) return;

} else if (externalQueryParam !== undefined) {
    this.currentFilter.query = externalQueryParam;
    this.currentPage = 1;
}

this.onEntitySelect(null);

try {
    this.isLoadingData = true;

    if (createdNewEntity && entityId && !this.currentFilter.query) {
        this.currentFilter.filtersApplied = [{
            property: this.currentEntityIdKey,
            operation: "eq",
            value: entityId
        }];

        this.currentFilter.query = `${this.currentEntityIdKey}_eq=${entityId}`;
    }

    // --- 2. Fetch Data ---
    const { entities, total, totalFiltered, pageCount } = await this.entityService.getAllEntities({
        page: this.currentPage,
        limit: limit,
        query: this.currentFilter.query,
        clearCache: clearCacheParam,
        apiType: this.currentApiType,
        entity: currentEntityType
    });

    // If the global ID has changed since this function was called, it means a
    // newer request is in progress. We should discard this response.
    if (loadId !== this.currentDataLoadId) {
        return;
    }

    // Store the results on the controller.
    this.currentTable = entities;
    this.currentColumns = this.entityService.getCachedEntityColumns();
    this.currentTotal = total;
    this.currentTotalFiltered = totalFiltered;
    this.currentPageCount = pageCount;

    if (pageCount) {
        this.currentTotalPages = pageCount;
    } else {
        this.currentTotalPages = 1;
    }

    // --- 3. Conditionally Enrich Data ---
    if (isOpportunity && this.currentTable.length > 0) {
        this.isAdmin = this.authService.isCurrentUserAdmin;
        this.hasPipelineRole = this.authService.hasRoleForCurrentTenant("Pipelines Viewer") || this.authService.hasRoleForCurrentTenant("Pipelines Manager");
        if (this.isAdmin || this.hasPipelineRole) {
            const { entities: pipelines } = await this.entityService.getAllEntities({ entity: "pipeline", limit: "ALL", apiType: this.currentApiType });
            const { entities: pipelineStages } = await this.entityService.getAllEntities({ entity: "pipelinestage", limit: "ALL", apiType: this.currentApiType });
            this.utilityService.mapPipelineStageIdToPipelineStageName(this.currentTable, pipelineStages);
            this.currentPipelines = pipelines;
            this.currentPipelineStages = pipelineStages;
            this.currentFilter.targetValues = {
                pipelineId: this.utilityService.generateLabelValueArray({
                    entityArray: pipelines,
                    labelKey: "name",
                    valueKey: "pipelineId"
                }),
                pipelineStageId: this.utilityService.generateLabelValueArray({
                    entityArray: pipelineStages,
                    labelKey: "name",
                    valueKey: "pipelineStageId"
                })
            };
        }
    }

    // --- 4. Sync Grid Selection ---
    // if (createdNewEntity && entityId) {
    //     this.onEntitySelect(null);
    //     _scrollToAndSelectRow(entityId, this);
    // } 

    if (this.isExportingEntity && this.currentRowsForExport && this.currentRowsForExport.length > 0) {
        this.initiateExport();

        this.currentSelectedRows = _getExportableRowsFromCurrentPage(this);
        // _syncGridSelection(this);
    }

} catch (error) {
    console.error("Error during onPageChange data load:", error);
    this.utilityService.toast("Failed to load data for current tab.", "ERROR");
    this.currentTable = []; // Clear table data on error
} finally {
    // Delay boolean update to ensure digest cycle trigger
    this.$timeout(() => {
        if (loadId === this.currentDataLoadId) {
            this.isLoadingData = false;
        }
    }, 500);
}

/**
 * Helper function to synchronize the ui-grid's selected rows with a master list.
 * Safe to call even if the table is still loading.
 * @private
 */
function _syncGridSelection(ctx) {
    const MAX_RETRIES = 20;
    let attempts = 0;

    function attemptSync() {
        try {
            if (!ctx.currentRowsForExport || ctx.currentRowsForExport.length === 0) {
                return;
            }

            const tableElement = document.querySelector('bln-table');
            const scope = tableElement ? angular.element(tableElement).scope() : null;

            const ctrl = scope?.$$childTail?.$ctrl;
            const gridApi = ctrl?.gridApi;

            if (!gridApi) {
                if (attempts < MAX_RETRIES) {
                    attempts++;
                    setTimeout(attemptSync, 100);
                } else {
                    console.warn("Timed out waiting for bln-table gridApi in _syncGridSelection");
                }
                return;
            }

            const deregisterEvent = gridApi.core.on.rowsRendered(null, () => {
                try {
                    const selectedIds = new Set(ctx.currentRowsForExport.map(row => row[ctx.currentEntityIdKey]));

                    let hasChanges = false;

                    gridApi.grid.rows.forEach(row => {
                        if (selectedIds.has(row.entity[ctx.currentEntityIdKey])) {
                            gridApi.selection.selectRow(row.entity);
                            hasChanges = true;
                        }
                    });

                    if (hasChanges && gridApi) {
                        gridApi.selection.raise.rowSelectionChangedBatch();
                    }

                } catch (innerError) {
                    console.error("Error during grid row selection:", innerError);
                } finally {
                    deregisterEvent();
                }
            });

        } catch (e) {
            console.error("Critical error in _syncGridSelection:", e);
        }
    }

    attemptSync();
}

/**
 * Finds a specific entity in the grid by its ID, scrolls to make it visible, and selects it.
 * Waits for the table component to be fully ready before executing.
 * @private
 * @param {string|number} entityId - The ID of the entity to find and select.
 */
function _scrollToAndSelectRow(entityId, ctx) {
    const MAX_RETRIES = 20;
    let attempts = 0;

    function attemptScroll() {
        try {
            if (!entityId) {
                return;
            }

            const tableElement = document.querySelector('bln-table');
            const scope = tableElement ? angular.element(tableElement).scope() : null;

            const ctrl = scope?.$$childTail?.$ctrl;
            const gridApi = ctrl?.gridApi;

            if (!gridApi) {
                if (attempts < MAX_RETRIES) {
                    attempts++;
                    setTimeout(attemptScroll, 100);
                } else {
                    console.warn(`Timed out waiting for bln-table gridApi in _scrollToAndSelectRow for ID: ${entityId}`);
                }
                return;
            }

            const deregisterEvent = gridApi.core.on.rowsRendered(null, () => {
                try {
                    const targetRow = gridApi.grid.rows.find(row =>
                        row.entity[ctx.currentEntityIdKey] === entityId
                    );

                    if (targetRow) {
                        gridApi.core.scrollTo(targetRow.entity, null);
                        gridApi.selection.selectRow(targetRow.entity);

                        if (gridApi) {
                            gridApi.selection.raise.rowSelectionChanged();
                        }

                        deregisterEvent();
                    } else {
                        deregisterEvent();
                    }
                } catch (innerError) {
                    console.error("Error executing scroll/select logic:", innerError);
                    deregisterEvent();
                }
            });

        } catch (e) {
            console.error("Critical error in _scrollToAndSelectRow:", e);
        }
    }

    attemptScroll();
}

/**
 * Iterates over the current table data and returns only the rows that are present in the export list.
 * @returns {Array} The subset of rows from currentTable that are marked for export.
 */
function _getExportableRowsFromCurrentPage(ctx) {
    try {
        if (!ctx.currentTable || !ctx.currentTable.length) {
            return [];
        }

        if (!ctx.currentRowsForExport || !ctx.currentRowsForExport.length) {
            return [];
        }

        const idKey = ctx.currentEntityIdKey;
        const exportIds = new Set(ctx.currentRowsForExport.map(row => row[idKey]));

        return ctx.currentTable.filter(row => exportIds.has(row[idKey]));

    } catch (e) {
        console.error("Error filtering exportable rows from current page:", e);
        return [];
    }
}

if (!this.isAddingEntity && this.currentForm !== null) this.utilityService.clearForm(this.currentForm);

this.isAddingEntity = !this.isAddingEntity;

if (this.isAddingEntity) this.isSidePanelVisible = true;
else this.isSidePanelVisible = false;

if (!this.isEditingEntity && this.currentForm !== null) this.utilityService.clearForm(this.currentForm);
this.isEditingEntity = !this.isEditingEntity;

if (this.isEditingEntity) this.utilityService.populateForm(this.currentForm, this.currentEntity);

this.isSendingData = true;

const fileNameMap = {
    contact: "Exported_Contacts",
    company: "Exported_Companies",
    opportunity: "Exported_Opportunities"
};
const entityType = this.currentEntityType;

if (!fileNameMap[entityType]) {
    this.utilityService.toast("Invalid entity type for export", "ERROR");
    this.isSendingData = false;
    return;
}

const capitalizedEntityType = entityType.charAt(0).toUpperCase() + entityType.slice(1);
const currentExportFormat = this.currentExportFormat;
const fileExtension = currentExportFormat === "excel" ? "xlsx" : currentExportFormat;
const defaultFileName = `${fileNameMap[entityType]}.${fileExtension}`;
const batchEndpoint = `/export/${capitalizedEntityType}`;
const endpoint = new URL(`${this.dataService.apiBaseUrl}${batchEndpoint}`);

endpoint.searchParams.set('format', currentExportFormat);

if (this.currentRowsForExport?.length) {
    const idPropertyName = `${entityType}Id`;
    const entityIds = this.currentRowsForExport.map(row => row[idPropertyName]);
    endpoint.searchParams.set('entityIds', entityIds.join(','));
} else {
    let limit = 20;
    let offset = 0;
    const modalInputFields = [
        {
            label: "Limit",
            type: "number",
            value: limit,
            placeholder: "Default: 20 records",
            tooltip: "Limits how many records to export",
            number: {
                min: 1
            }
        },
        {
            label: "Offset",
            type: "number",
            value: offset,
            placeholder: "Default: 0 records",
            tooltip: "Starts the export from this record number",
            number: {
                min: 0
            }
        }
    ];

    try {
        const modalResult = await this.$modal.open("confirm-action-modal", {
            modalHeaderTitle: "Export All",
            modalInputFields: modalInputFields,

            // --- REFACTORED PART ---

            // Pass a FUNCTION for the disabled state.
            // The modal will call this function whenever the modalInputFields change.
            // It passes the current state of the fields as an argument.
            modalOKButtonDisabled: (currentFields) => {
                const limitValue = currentFields[0].value;
                const offsetValue = currentFields[1].value;

                // The button is disabled if the condition is true.
                return limitValue < 1 || offsetValue < 0;
            },

            // Pass a FUNCTION for the tooltip as well.
            modalOKButtonTooltip: (currentFields) => {
                const limitValue = currentFields[0].value;
                const offsetValue = currentFields[1].value;

                // Using if statements is often clearer than a nested ternary.
                if (limitValue < 1) {
                    return "Limit cannot be less than 1";
                }
                if (offsetValue < 0) {
                    return "Offset cannot be less than 0";
                }

                // Return null or an empty string when there is no tooltip to show.
                return null;
            }
        });

        if (modalResult?.result === "ok") {
            limit = modalResult.modalInputFields[0].value ?? limit;
            offset = modalResult.modalInputFields[1].value ?? offset;
            endpoint.searchParams.set('limit', limit);
            endpoint.searchParams.set('offset', offset);
        } else {
            this.isSendingData = false;
            return;
        }
    } catch (error) {
        console.error("Modal error:", error);
        this.utilityService.toast("Error during export configuration", "ERROR");
        this.isSendingData = false;
        return;
    }
}

try {
    const response = await fetch(endpoint.toString(), {
        method: "GET",
        headers: this.authService.getHeaders(),
    });

    if (!response.ok) {
        const errorMessage = await response.text();
        throw new Error(errorMessage || `Failed to export ${entityType}s`);
    }

    // --- REFACTORED PART: Handle JSON format separately ---
    let fileBlob;

    if (currentExportFormat === 'json') {
        // For JSON, we need to parse the response and extract the entity array.
        const responseData = await response.json();

        // Intelligently find the array within the response object.
        const entities = responseData[entityType] || responseData.entity || responseData;

        // Re-serialize ONLY the entities array into a nicely formatted string.
        const jsonString = JSON.stringify(entities, null, 2);
        fileBlob = new Blob([jsonString], { type: 'application/json' });
    } else {
        // For all other formats (xlsx, csv), treat the whole response as the file.
        fileBlob = await response.blob();
    }

    // Use a helper to trigger the download.
    _triggerFileDownload(fileBlob, defaultFileName);

} catch (error) {
    this.utilityService.toast(error?.message || `An unexpected error occurred during export`, "ERROR");
} finally {
    this.isSendingData = false;
}

/**
 * Helper function to create a link and trigger a browser download.
 * @private
 */
function _triggerFileDownload(blob, fileName) {
    const url = window.URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    // Clean up by removing the link and revoking the object URL.
    document.body.removeChild(link);
    window.URL.revokeObjectURL(url);
}

const tableContainer = document.querySelector("#main-body-container .table-container");
if (tableContainer) {
    tableContainer.removeAttribute("style");
}

this.currentSelectedRows.length = 0;
this.currentRowsForExport.length = 0;
this.isExportingEntity = false;

// Set loading state at the beginning
this.isSendingData = true;

try {
    const METHOD = "POST";
    const { currentEntityType, currentApiType, currentForm } = this;
    const requestBody = this.dataService.buildRequestBody(METHOD, currentForm);

    // --- First API Call ---
    const initialResponse = await this.dataService.sendData(
        currentEntityType,
        METHOD,
        requestBody,
        { apiType: currentApiType }
    );

    // If the result is not OK, throw an error to be caught by the catch block
    if (initialResponse.result !== "OK") {
        throw new Error(initialResponse.message);
    }

    // --- Conditional Second API Call ---
    if (currentEntityType === "tenant") {
        delete requestBody.active; // Modify the request body for the second call
        const crmResponse = await this.dataService.sendData(
            currentEntityType,
            METHOD,
            requestBody,
            { apiType: "crm" } // Use the new options
        );

        if (crmResponse.result !== "OK") {
            throw new Error(crmResponse.message);
        }

        await this.authService.setSaasAuth();
    }

    // --- Success Actions ---
    // These now run only after all API calls have successfully completed
    this.isAddingEntity = false;
    this.utilityService.clearForm(currentForm);

    const newEntityId = initialResponse[this.currentEntityType][this.currentEntityIdKey];
    const newEntityName = initialResponse[this.currentEntityType].name ?? initialResponse[this.currentEntityType].fullName ?? null;

    const onPageChangeOptions = {
        createdNewEntity: true,
        entityId: newEntityId
    };

    if (this.currentFilter.query) {
        this.notificationService.notify({
            alertType: "success",
            alertDescription: `New ${this.currentEntityType} ${newEntityName ? `"${newEntityName}" `: ""} has been created but is not currently visible.`,
            displayActionText: true,
            actionTextLabel: "[Click Here to View]",
            onActionTextClick: () => {
                this.currentFilter.column = this.currentEntityIdKey;
                this.currentFilter.operation = "eq";
                this.currentFilter.target = newEntityId;
                this.currentFilter.filtersApplied = [{
                    property: this.currentEntityIdKey,
                    operation: "eq",
                    value: newEntityId
                }];
                this.onPageChange(undefined, `${this.currentEntityIdKey}=${newEntityId}`, undefined, onPageChangeOptions);
            },
            dismissIn: 10_000
        });
        return;
    }

    this.onPageChange(undefined, undefined, undefined, onPageChangeOptions);

} catch (error) {
    // Centralized error handling for both network failures and API errors
    this.utilityService.toast(error.message, "ERROR");
} finally {
    // This block will always run, ensuring the loading state is reset
    this.isSendingData = false;
}

