if (!this.currentRowsForExport) {
    this.currentRowsForExport = [];
}

this.isExportingEntity = true;

const MAX_RETRIES = 20;
let attempts = 0;

const attemptRegisterListeners = (ctx) => {
    try {
        const tableElement = document.querySelector('bln-table');
        const scope = tableElement ? angular.element(tableElement).scope() : null;
        const childScope = scope ? scope.$$childTail : null;
        const gridCtrl = childScope && childScope.$ctrl;
        const gridApi = gridCtrl && gridCtrl.gridApi;

    if (!gridApi || !gridApi.selection) {
            if (attempts < MAX_RETRIES) {
                attempts++;
                ctx.$timeout(attemptRegisterListeners, 100);
            } else {
                console.warn("Timed out waiting for bln-table gridApi.selection in initiateExport.");
                this.utilityService.toast("Could not initialize table export. Please try again.", "WARNING");
                // this.isExportingEntity = false;
            }
            return;
        }

        const currentEntityIdKey = this.currentEntityIdKey;

        gridApi.selection.on.rowSelectionChanged(childScope, (row) => {
            if (row.isSelected) {
                const isAlreadySelected = this.currentRowsForExport.some(
                    selectedRow => selectedRow[currentEntityIdKey] === row.entity[currentEntityIdKey]
                );
                if (!isAlreadySelected) {
                    this.currentRowsForExport.push(row.entity);
                }
            } else {
                const indexToRemove = this.currentRowsForExport.findIndex(
                    selectedRow => selectedRow[currentEntityIdKey] === row.entity[currentEntityIdKey]
                );
                if (indexToRemove > -1) {
                    this.currentRowsForExport.splice(indexToRemove, 1);
                }
            }
        });

        gridApi.selection.on.rowSelectionChangedBatch(childScope, (rows) => {
            if (rows.length > 0 && rows[0].isSelected) {
                // Add Batch
                const selectedIds = new Set(this.currentRowsForExport.map(r => r[currentEntityIdKey]));
                rows.forEach(row => {
                    if (!selectedIds.has(row.entity[currentEntityIdKey])) {
                        this.currentRowsForExport.push(row.entity);
                    }
                });
            } else {
                const deselectedIdsOnPage = new Set(rows.map(r => r.entity[currentEntityIdKey]));
                this.currentRowsForExport = this.currentRowsForExport.filter(
                    selectedRow => !deselectedIdsOnPage.has(selectedRow[currentEntityIdKey])
                );
            }
        });

    } catch (e) {
        console.error("Error initializing export listeners:", e);
        // this.isExportingEntity = false;
    }
};

attemptRegisterListeners(this);

try {
    disableNavFlexBasis();
    onWindowResize(this);
    window.addEventListener("resize", () => onWindowResize(this));
} catch (e) {
    console.error("Error initializing layout", e);
}

function onWindowResize(ctx) {
    const box = document.getElementById("box");
    const width = ctx.$window.innerWidth;

    if (width <= 1024) {
        ctx.isMobile = true;
        box.style.flexDirection = "column";
    } else {
        ctx.isMobile = false;
        box.style.flexDirection = "row";
    }
}

function disableNavFlexBasis() {
    const nav = document.getElementById("nav");

    if (nav) {
        nav.style.flexBasis = null;
    }
}

const columnNames = columns.map((c) => c.label);
this.entityService.setCachedEntityColumns(this.dataService.processData.generateColumnDefinitions(columnNames, {}));
this.currentColumns = this.entityService.getCachedEntityColumns();
this.currentDisplayColumnConfig = { columnNames, options: {} };
